ST.xhtml:
// S0: Manual mode (initial step)
// Jog, teach and the commands are handled in MAIN (ST) while nStep = 0.
MAIN.nStep := 0;

// S10: Homing - arm back (until B10)
MAIN.nStep := 10;
MAIN.bHomed := FALSE;
MAIN.M4_Back := TRUE;

// S11: Homing - X to B1 and Y to B4 at the same time
MAIN.nStep := 11;
MAIN.M2_Back := NOT MAIN.B1;                     // each axis stops at its own switch
MAIN.M3_Up   := NOT MAIN.B4;

// S12: Homing - wait 0.5 s (tonSettle in MAIN), then set both positions to 0
MAIN.nStep := 12;
IF MAIN.tonSettle.Q THEN
    MAIN.nPosX := 0;
    MAIN.nPosY := 0;
    MAIN.bHomed := TRUE;
END_IF

// S70 = E70 Entry step: wait until the crane is at home (B1 * B10 * B4)
MAIN.nStep := 70;
MAIN.bShelfSelected := FALSE;                    // ignore any old shelf selection

// S71: Get PosX and PosY from the arrays according to the operator's choice
// (nStep = 71 shows the 3x3 shelf selection on the HMI)
MAIN.nStep := 71;
MAIN.bPosXReached := FALSE;
MAIN.bPosYReached := FALSE;

IF MAIN.bShelfSelected THEN
    MAIN.bShelfSelected := FALSE;
    IF MAIN.nSelColumn >= 1 AND MAIN.nSelColumn <= 3 AND MAIN.nSelRow >= 1 AND MAIN.nSelRow <= 3 THEN
        MAIN.nTargetX := MAIN.xPosition[MAIN.nSelColumn];
        MAIN.nTargetY := MAIN.yPosition[MAIN.nSelRow];
        MAIN.bPositionFound := TRUE;
    END_IF
END_IF

// S72 (Y part): Y moves to the shelf height (M3_Down via ACT_Positioning)
MAIN.nStep := 72;
MAIN.bPositionFound := FALSE;
MAIN.bDriveY := TRUE;

// S72 (X part): X moves to the shelf column (M2_Forward via ACT_Positioning)
MAIN.nStep := 72;
MAIN.bPositionFound := FALSE;
MAIN.bDriveX := TRUE;

// S77: Both axes in position
MAIN.nStep := 77;
MAIN.bInPosition := TRUE;

// S73: Arm out under the pallet (until B9)
MAIN.nStep := 73;
MAIN.M4_Forward := TRUE;
MAIN.bInPosition := FALSE;
MAIN.nTargetY := MAIN.yPosition[MAIN.nSelRow] - MAIN.nLiftOffset;   // prepare the lift (up = smaller Y)
MAIN.bPosYReached := FALSE;

// S74: Lift the pallet off the shelf (M3_Up via ACT_Positioning)
MAIN.nStep := 74;
MAIN.bDriveY := TRUE;

// S78: Arm back with the pallet (until B10)
MAIN.nStep := 78;
MAIN.M4_Back := TRUE;

// S79: Get the delivery position (index 0 = conveyor)
MAIN.nStep := 79;
MAIN.nTargetX := MAIN.xPosition[0];              // DeliveryPosX
MAIN.nTargetY := MAIN.yPosition[0];              // DeliveryPosY
MAIN.bPosXReached := FALSE;
MAIN.bPosYReached := FALSE;
MAIN.bPositionFound := TRUE;

// S80/S81 (Y part): Y moves up or down to the delivery height.
// ACT_Positioning chooses the direction (M3_Up or M3_Down) by itself.
MAIN.nStep := 80;
MAIN.bPositionFound := FALSE;
MAIN.bDriveY := TRUE;

// S80/S81 (X part): X moves back to the conveyor (M2_Back via ACT_Positioning)
MAIN.nStep := 80;
MAIN.bPositionFound := FALSE;
MAIN.bDriveX := TRUE;

// S84: Both axes in position
MAIN.nStep := 84;
MAIN.bInPosition := TRUE;

// S85: Arm out over the conveyor (until B9)
MAIN.nStep := 85;
MAIN.M4_Forward := TRUE;
MAIN.bInPosition := FALSE;
MAIN.nTargetY := MAIN.yPosition[0] + MAIN.nLowerOffset;   // prepare lowering (down = larger Y)
MAIN.bPosYReached := FALSE;

// S86: Lower the pallet onto the conveyor (M3_Down via ACT_Positioning)
MAIN.nStep := 86;
MAIN.bDriveY := TRUE;

// S87: Arm back (until B10)
MAIN.nStep := 87;
MAIN.M4_Back := TRUE;

// S30: Manual - move X to xPosition[nTeachSlot] (target set in ACT_Manual)
MAIN.nStep := 30;
MAIN.bDriveX := TRUE;

// S31: Manual - move Y to yPosition[nTeachSlot] (target set in ACT_Manual)
MAIN.nStep := 31;
MAIN.bDriveY := TRUE;

InterfaceAsPlainText.xhtml:
PROGRAM SFC_Sequence
// =====================================================================
// SFC_Sequence (Sequential Function Chart)
// Homing and the automatic sequence (GRAFCET E70 .. S70).
// Called from MAIN every cycle. All variables are in MAIN (MAIN.xxx).
// Every step has one ST action (<step>_Active) that runs while the step is active.
// The motors are switched off in MAIN before this chart is called, so a step
// only has to switch ON what it needs.
// =====================================================================
VAR_INPUT
    SFCReset : BOOL;            // SFC flag: TRUE = chart back to the initial step S0 (STOP / homing timeout)
END_VAR
VAR
END_VAR
